'use client';
import { useState } from 'react';
import { useAuth } from '@/context/AuthContext';
import { X, Calendar, User, MapPin, CheckCircle, Home, Plus, ArrowUpDown } from 'lucide-react';
import LoginModal from './LoginModal';

export default function BookingModal({ isOpen, onClose, service }) {
  const { user } = useAuth();
  const [showLogin, setShowLogin] = useState(false);
  const [step, setStep] = useState(0); // 0: Select Lab, 1: Checkout, 2: Success
  const [selectedLab, setSelectedLab] = useState(null);
  const [formData, setFormData] = useState({
    name: 'User',
    date: new Date().toISOString().split('T')[0],
    address: 'New Delhi, India'
  });

  const LABS = [
    { id: 101, name: 'Total Diagnostics Care', location: 'Kirti Nagar, New Delhi', time: '24 hrs', price: 184, oldPrice: 200, discount: '8% off' },
    { id: 102, name: 'City X-Ray & Scan Clinic Pvt Ltd', location: 'Tilak Nagar, New Delhi', time: '24 hrs', price: 400, oldPrice: 500, discount: '20% off' },
    { id: 103, name: 'Cee Dee Diagnostics Pvt Ltd', location: 'Malviya Nagar, New Delhi', time: '12 hrs', price: 250, oldPrice: 300, discount: '15% off' },
  ];

  if (!isOpen || !service) return null;

  // Global Auth Check for Booking
  if (!user) {
      return <LoginModal isOpen={true} onClose={onClose} />;
  }

  // Handle Lab Selection
  const handleLabSelect = (lab) => {
      setSelectedLab(lab);
      setStep(1); // Move to checkout
  };

  const handleBooking = async () => {
       // Mock API call
       setStep(2);
  };

  // Determine pricing based on selected lab OR default to service price if skipping lab selection (for backward compat)
  const displayPrice = selectedLab ? selectedLab.price : service.price;
  const displayMrp = selectedLab ? selectedLab.oldPrice : (service.marketPrice || service.price * 1.5);
  const displayDiscount = selectedLab ? selectedLab.price - selectedLab.oldPrice : (displayPrice - displayMrp);

  return (
    <div style={{
      position: 'fixed', inset: 0, zIndex: 2000,
      background: 'rgba(0,0,0,0.5)',
      display: 'flex', alignItems: 'center', justifyContent: 'center'
    }}>
      <div style={{
        width: '100%', maxWidth: step === 0 ? '500px' : '450px', 
        background: '#fff', 
        padding: '0',
        borderRadius: '16px',
        position: 'relative', 
        boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.1)',
        overflow: 'hidden',
        maxHeight: '90vh',
        display: 'flex', flexDirection: 'column'
      }}>
        
        {/* Step 0: Select Lab (New) */}
        {step === 0 && (
            <>
                <div style={{ padding: '1.5rem', borderBottom: '1px solid #f3f4f6', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <h3 style={{ fontSize: '1.2rem', color: '#111827', fontWeight: 'bold' }}>Select a lab for your visit</h3>
                    <button onClick={onClose} style={{ background: 'transparent', border: 'none', cursor: 'pointer', color: '#6b7280' }}>
                        <X size={24} />
                    </button>
                </div>

                <div style={{ padding: '1.5rem', overflowY: 'auto', background: '#f9fafb' }}>
                    {/* Sort Pill */}
                    <div style={{ marginBottom: '1.5rem' }}>
                        <button style={{ 
                            display: 'flex', alignItems: 'center', gap: '6px', 
                            background: '#111827', color: '#fff', 
                            padding: '6px 12px', borderRadius: '20px', fontSize: '0.85rem', border: 'none'
                        }}>
                             Recommended <ArrowUpDown size={14} />
                        </button>
                    </div>

                    {/* Lab Cards */}
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                        {LABS.map(lab => (
                            <div key={lab.id} style={{ background: '#fff', border: '1px solid #e5e7eb', borderRadius: '12px', padding: '1.2rem', cursor: 'pointer', display: 'flex', gap: '1rem' }} onClick={() => handleLabSelect(lab)}>
                                {/* Radio Circle */}
                                <div style={{ 
                                    minWidth: '20px', height: '20px', borderRadius: '50%', border: '2px solid #d1d5db', marginTop: '4px' 
                                }}></div>
                                
                                <div style={{ flex: 1 }}>
                                    <h4 style={{ fontSize: '1rem', fontWeight: 'bold', color: '#111827', marginBottom: '4px' }}>{lab.name}</h4>
                                    <p style={{ fontSize: '0.9rem', color: '#6b7280', marginBottom: '0.5rem' }}>{lab.location}</p>
                                    
                                    <p style={{ fontSize: '0.9rem', color: '#2563eb', marginBottom: '0.5rem' }}>
                                        Get report in <span style={{ fontWeight: 'bold' }}>{lab.time}</span>
                                    </p>

                                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '0.5rem' }}>
                                        <span style={{ fontSize: '1.1rem', fontWeight: 'bold', color: '#111827' }}>₹{lab.price}</span>
                                        <span style={{ fontSize: '0.9rem', textDecoration: 'line-through', color: '#9ca3af' }}>₹{lab.oldPrice}</span>
                                        <span style={{ fontSize: '0.85rem', color: '#059669', fontWeight: 'bold' }}>{lab.discount}</span>
                                    </div>

                                    <div style={{ fontSize: '0.85rem', color: '#ff6f61', textDecoration: 'underline', fontWeight: '500' }}>
                                        Know More
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* Best Price Banner (Mock) */}
                    <div style={{ marginTop: '1rem', background: '#fff', border: '1px solid #e5e7eb', borderRadius: '12px', overflow: 'hidden' }}>
                        <div style={{ background: '#059669', color: '#fff', fontSize: '0.75rem', fontWeight: 'bold', padding: '2px 8px', width: 'fit-content', borderBottomRightRadius: '8px' }}>
                            Best Price
                        </div>
                        <div style={{ padding: '1rem', display: 'flex', gap: '1rem', alignItems: 'center' }}>
                             <div style={{ minWidth: '20px', height: '20px', borderRadius: '50%', border: '2px solid #d1d5db' }}></div>
                             <span style={{ fontWeight: 'bold', color: '#111827' }}>Cee Dee Diagnostics Pvt Ltd</span>
                        </div>
                    </div>
                </div>
            </>
        )}

        {/* Step 1 & 2: Checkout logic (Existing, just slightly adjusted for layout) */}
        {(step === 1 || step === 2) && (
            <>
                <div style={{ padding: '1rem 1.5rem', borderBottom: '1px solid #f3f4f6', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <h3 style={{ fontSize: '1.1rem', color: '#111827' }}>{step === 1 ? 'Booking Summary' : 'Booking Status'}</h3>
                    <button onClick={() => setStep(0)} style={{ background: 'transparent', border: 'none', cursor: 'pointer', color: '#6b7280', fontSize: '0.9rem', marginRight: 'auto', marginLeft: '10px' }}>
                        &lt; Back
                    </button>
                    <button onClick={onClose} style={{ background: 'transparent', border: 'none', cursor: 'pointer', color: '#6b7280' }}>
                        <X size={24} />
                    </button>
                </div>

                <div style={{ padding: '1.5rem', overflowY: 'auto' }}>
                    {step === 1 ? (
                        <>
                        {/* Selected Item */}
                            <div style={{ marginBottom: '2rem' }}>
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.5rem' }}>
                                     <div style={{ fontSize: '0.85rem', color: '#6b7280' }}>Selected Lab: <b>{selectedLab?.name}</b></div>
                                     <button 
                                         onClick={() => setStep(0)} 
                                         style={{ 
                                             color: '#ff6f61', 
                                             background: 'transparent', 
                                             border: 'none', 
                                             fontWeight: '600', 
                                             fontSize: '0.9rem', 
                                             cursor: 'pointer' 
                                         }}
                                     >
                                         Change
                                     </button>
                                </div>
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', border: '1px solid #e5e7eb', padding: '1rem', borderRadius: '8px' }}>
                                    <div>
                                        <div style={{ fontWeight: '600', color: '#111827', marginBottom: '4px' }}>{service.name}</div>
                                        <div style={{ fontSize: '0.9rem', color: '#059669', fontWeight: '500' }}>{selectedLab?.discount || 'Best Rate'}</div>
                                    </div>
                                    <div style={{ textAlign: 'right' }}>
                                        <div style={{ fontWeight: 'bold' }}>₹{displayPrice}</div>
                                        {displayMrp && <div style={{ fontSize: '0.8rem', textDecoration: 'line-through', color: '#9ca3af' }}>₹{displayMrp}</div>}
                                    </div>
                                </div>
                            </div>

                            {/* Bill Summary */}
                            <div style={{ marginBottom: '2rem' }}>
                                <h4 style={{ fontSize: '1rem', marginBottom: '1rem', color: '#111827' }}>Bill summary</h4>
                                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.5rem', fontSize: '0.9rem', color: '#4b5563' }}>
                                    <span>Total MRP</span>
                                    <span>₹{displayMrp}</span>
                                </div>
                                <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '1rem', borderTop: '1px solid #e5e7eb', paddingTop: '1rem', fontWeight: 'bold', fontSize: '1.1rem', color: '#111827' }}>
                                    <span>To be paid</span>
                                    <span>₹{displayPrice}</span>
                                </div>
                            </div>

                            {/* Address Section */}
                            <div style={{ marginBottom: '2rem' }}>
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px', color: '#111827', fontWeight: '600' }}>
                                        <Home size={18} /> Billing address
                                    </div>
                                    <button style={{ color: '#ef4444', background: 'transparent', border: 'none', fontWeight: '600', fontSize: '0.9rem', cursor: 'pointer' }}>Add Address</button>
                                </div>
                                <div style={{ fontSize: '0.9rem', color: '#6b7280', paddingLeft: '26px' }}>
                                    {formData.address}
                                </div>
                            </div>
                        </>
                    ) : (
                        <div style={{ textAlign: 'center', padding: '2rem 1rem' }}>
                            <CheckCircle size={64} color="#059669" style={{ marginBottom: '1.5rem', margin: '0 auto' }} />
                            <h2 style={{ fontSize: '1.5rem', marginBottom: '1rem' }}>Booking Confirmed!</h2>
                            <p style={{ color: '#6b7280' }}>Your appointment at {selectedLab?.name} is scheduled.</p>
                        </div>
                    )}
                </div>

                {/* Footer Button - Sticky */}
                {step === 1 && (
                    <div style={{ padding: '1rem 1.5rem', borderTop: '1px solid #f3f4f6' }}>
                        <button 
                            onClick={handleBooking}
                            style={{ 
                                width: '100%', 
                                background: '#ff6f61', 
                                color: '#fff', 
                                border: 'none', 
                                padding: '1rem', 
                                borderRadius: '8px', 
                                fontWeight: '600', 
                                fontSize: '1rem',
                                cursor: 'pointer'
                            }}
                        >
                            Pay ₹{displayPrice}
                        </button>
                    </div>
                )}
            </>
        )}
      </div>
    </div>
  );
}
